(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.28)*18 + Math.cos(y*0.013-t*0.22)*12;
  const w1y = Math.cos(y*0.02-t*0.24)*18 + Math.sin(x*0.016+t*0.32)*12;
  const w2x = Math.sin(x*0.009-t*0.15)*25 + Math.cos((x+y)*0.007+t*0.1)*15;
  const w2y = Math.cos(y*0.011+t*0.18)*25 + Math.sin((x-y)*0.008-t*0.12)*15;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.8],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.2],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.9],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.1],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.7],
    [80+Math.sin(t*0.65+3)*70, 40+Math.cos(t*0.45+2)*50, 0.14, 1.3, 0.6],
    [400+Math.cos(t*0.55+1)*60, 200+Math.sin(t*0.75+4)*40, 0.11, 2.1, 1.3]
  ];
  let aS=0, iS=0, dS=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const wave = Math.sin(d*f-t*sp);
    aS += wave*w;
    iS += Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    dS += Math.sin(d*f*1.3-t*sp*0.4+2.8)*w*0.5;
  }
  aS/=6; iS/=6; dS/=6;
  const bg1 = (Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2;
  const bg2 = Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2;
  const bg3 = Math.sin(sx*0.065-t*0.9)*Math.sin(sy*0.055+t*0.7)*0.3;
  const bg = bg1+bg2+bg3;
  const dist = Math.sqrt((sx-cx)**2+(sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const sp1 = Math.sin(dist*0.05-ang*3-t*1.5);
  const sp2 = Math.sin(dist*0.04+ang*4-t*1.2);
  const sp3 = Math.sin(dist*0.08-ang*2+t*0.8)*0.5;
  const spiral = (sp1+sp2)*0.35+sp3*0.15;
  const lap = Math.sin(sx*0.22)*Math.sin(sy*0.22)+Math.sin((sx+sy)*0.17+t*0.6)*0.4+Math.sin((sx-sy)*0.14-t*0.5)*0.3;
  const diff = Math.tanh(lap*1.8)*0.35;
  const react = Math.tanh((aS - iS*0.65 + bg*0.25 + spiral + dS*0.15)*2.0);
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.25;
  const micro = Math.sin(sx*0.35+t*3)*Math.sin(sy*0.35-t*2.5)*0.08;
  const blend = react*0.6 + cell*0.2 + diff*0.15 + micro;
  const v = blend*0.5+0.5;
  const pal = [
    [5,12,52],[10,35,85],[12,65,115],[18,110,135],
    [45,155,145],[120,185,130],[195,195,85],
    [225,165,60],[215,115,55],[185,70,60],
    [140,40,65],[85,22,55],[40,14,48],[5,12,52]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.82+Math.sin(react*Math.PI)*0.18;
  const edge = Math.abs(react)>0.72?1.12:Math.abs(react)>0.5?1.04:0.96;
  const glow = Math.max(0, 1-Math.abs(react)*1.3)*0.08;
  return [
    Math.min(255, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*60))|0,
    Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*40))|0,
    Math.min(255, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*80))|0
  ];
}
